import pyomo.environ as pyo

DATA = {
    "CARGO": [1, 2, 3, 4],
    "cost": {1: 4, 2: 3, 3: 5, 4: 7},
    "lb": {1: 0, 2: 0, 3: 0, 4: 0},
    "ub": {1: 700, 2: 600, 3: 400, 4: 500},
    "cap_12": 1000,   # x1 + x2 <= 1000
    "cap_34": 800,    # x3 + x4 <= 800
    "dem_13": 500,    # x1 + x3 >= 500
    "dem_24": 600,    # x2 + x4 >= 600
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.CARGO = pyo.Set(initialize=d["CARGO"])

    def ship_bounds(m, c):
        return (d["lb"][c], d["ub"][c])

    model.ship = pyo.Var(
        model.CARGO,
        domain=pyo.NonNegativeIntegers,
        bounds=ship_bounds,
    )

    def obj_rule(m):
        return sum(d["cost"][c] * m.ship[c] for c in m.CARGO)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def cap12_rule(m):
        return m.ship[1] + m.ship[2] <= d["cap_12"]

    model.cap_12 = pyo.Constraint(rule=cap12_rule)

    def cap34_rule(m):
        return m.ship[3] + m.ship[4] <= d["cap_34"]

    model.cap_34 = pyo.Constraint(rule=cap34_rule)

    def dem13_rule(m):
        return m.ship[1] + m.ship[3] >= d["dem_13"]

    model.dem_13 = pyo.Constraint(rule=dem13_rule)

    def dem24_rule(m):
        return m.ship[2] + m.ship[4] >= d["dem_24"]

    model.dem_24 = pyo.Constraint(rule=dem24_rule)

    return model


